  dryRun: boolean;
  willChange: number;
  changed: number;
  /** v1.1 R1: só em reajuste de preço (preço antigo, novo e "Você recebe" por item; a mesma contagem do botão "Selecionar os N") */
  preview?: BulkPreviewItem[];
