/**
 * DEC-053: faixa de chegada (preparo da loja + despacho + deslocamento, com folga de +-15 min), SEMPRE como faixa e nunca como número único. `fromAt`/`toAt` são o horário de relógio ('Chega entre 15:40 e 16:40'); `minMinutes`/`maxMinutes`, os minutos a partir de agora. Passando do teto `entrega_max_min` (120) NO FIM DA FAIXA (DEC-054: estimativa + folga) a loja não entrega para o endereço: `available=false` e `eta=null` ('fora da área').
 */
export interface EtaRange {
  minMinutes: number;
  maxMinutes: number;
  fromAt: string;
  toAt: string;
}

/**
 * F4: por que não entrega agora, com `available=false`. `LOGISTICS_CLOSED`: fora do horário ou o fim da faixa passa do fechamento (`logisticsOpensAt` traz a volta); `LOGISTICS_PAUSED`: entregas pausadas pelo admin (sem previsão); `OUT_OF_RANGE`: fora do raio/alcance ou a loja não faz entrega. Nulo quando entrega. Campo novo opcional.
 * @nullable
 */
export type StoreDeliveryUnavailableReason = typeof StoreDeliveryUnavailableReason[keyof typeof StoreDeliveryUnavailableReason] | null;


export const StoreDeliveryUnavailableReason = {
  OUT_OF_RANGE: 'OUT_OF_RANGE',
  LOGISTICS_CLOSED: 'LOGISTICS_CLOSED',
  LOGISTICS_PAUSED: 'LOGISTICS_PAUSED',
} as const;

export interface StoreDelivery {
  /** DEC-053: faixa calculada para a posição; nulo quando a loja não entrega aí. */
  eta?: EtaRange | null;
  /**
     * BUG-016: com `available=false` por horário da logística, quando a entrega volta ("Entrega volta às HH:MM"); nulo em pausa do admin ou quando entrega normalmente.
     * @nullable
     */
  logisticsOpensAt?: string | null;
  /** Entrega na posição consultada (dentro do raio e de uma faixa) */
  available: boolean;
  /**
     * Taxa para a posição, antes de "grátis acima de X"
     * @nullable
     */
  feeCents: number | null;
  /** Taxa R$ 0 nessa posição */
  freeShipping: boolean;
  /** 0 = sem frete grátis por valor */
  freeAboveCents: number;
  minOrderCents: number;
  etaMinMinutes: number;
  etaMaxMinutes: number;
  /**
     * F4: por que não entrega agora, com `available=false`. `LOGISTICS_CLOSED`: fora do horário ou o fim da faixa passa do fechamento (`logisticsOpensAt` traz a volta); `LOGISTICS_PAUSED`: entregas pausadas pelo admin (sem previsão); `OUT_OF_RANGE`: fora do raio/alcance ou a loja não faz entrega. Nulo quando entrega. Campo novo opcional.
     * @nullable
     */
  unavailableReason?: StoreDeliveryUnavailableReason;
}

