/**
 * Entrada inválida (campo desconhecido, formato ou tamanho). `errors[]` lista os campos.
 */
export type ValidationErrorResponse = Problem;

/**
 * Não autenticado, token inválido ou sessão encerrada
 */
export type UnauthorizedResponse = Problem;

/**
 * Sem permissão (ou `REAUTH_REQUIRED`, `MFA_REQUIRED`, `EMAIL_VERIFICATION_REQUIRED`; com `X-View-As`: `VIEW_AS_READ_ONLY` para método, rota fora da lista ou cabeçalho vazio ou repetido; `VIEW_AS_EXPIRED` para credencial malformada, vencida, encerrada ou de outra loja, admin ou sessão)
 */
export type ForbiddenResponse = Problem;

/**
 * Não encontrado (também para recurso de outro usuário, sem revelar existência)
 */
export type NotFoundResponse = Problem;

/**
 * Conflito de estado ou duplicidade
 */
export type ConflictResponse = Problem;

/**
 * Convite inválido, usado, revogado ou vencido
 */
export type GoneResponse = Problem;

/**
 * Regra de negócio violada (senha fraca, fora da faixa...)
 */
export type UnprocessableResponse = Problem;

/**
 * Limite de tentativas. Header `Retry-After` em segundos.
 */
export type TooManyRequestsResponse = Problem;

/**
 * Indisponibilidade momentânea sob saturação (pool do banco esgotado ou consulta cancelada por tempo, BUG-035): `code` `SERVICE_UNAVAILABLE`, `Retry-After` em segundos, sem pilha nem SQL. O app tenta de novo depois do prazo. Não é erro do pedido
 */
export type ServiceUnavailableResponse = Problem;

/**
 * Corpo acima do limite da rota (`code` `PAYLOAD_TOO_LARGE`)
 */
export type PayloadTooLargeResponse = Problem;

/**
 * `PRODUCT_VERSION_CONFLICT`: o produto mudou depois da versão informada ("O lojista alterou este produto agora"); traz a versão atual em `current` (só neste `code`). Também cobre as demais regras de conflito da rota (`STOCK_BELOW_RESERVED`, `STORE_NOT_APPROVED`, `OPEN_ORDERS`, `IDEMPOTENCY_IN_PROGRESS`), que mantêm o corpo antigo do `Problem` (sem `current`); por isso `current` é opcional no schema (tech-lead I1)
 */
export type ProductVersionConflictResponse = ProductVersionConflictProblem;

/**
 * 409 das ações em massa: `BULK_VERSION_CONFLICT` (algum item mudou depois da prévia: `conflicts` com a versão atual; nada é aplicado), além de `STORE_NOT_APPROVED` e `IDEMPOTENCY_IN_PROGRESS` com o corpo antigo do `Problem`
 */
export type BulkVersionConflictResponse = BulkVersionConflictProblem;

/**
 * 422 do lote de rascunhos: validação (`VALIDATION_FAILED`) ou `DRAFT_LIMIT_REACHED` com `limit`, `draftCount` e `slotsAvailable` (`DraftLimitProblem`)
 */
export type DraftLimitUnprocessableResponse = DraftLimitProblem;

